from datetime import datetime, timedelta
from typing import Dict, List, Optional


class Appointment:
    def __init__(self, id: int, patient: str, doctor: str, start: datetime, end: datetime):
        self.id = id
        self.patient = patient
        self.doctor = doctor
        self.start = start
        self.end = end
        self.cancelled = False


class BlockedSlot:
    def __init__(self, doctor: str, start: datetime, end: datetime):
        self.doctor = doctor
        self.start = start
        self.end = end


class Scheduler:
    def __init__(self) -> None:
        self._next_id: int = 1
        self._appointments: Dict[int, Appointment] = {}
        self._blocked_slots: List[BlockedSlot] = []

    def _overlaps(self, start1: datetime, end1: datetime, start2: datetime, end2: datetime) -> bool:
        # Appointments that only touch do not overlap
        return max(start1, start2) < min(end1, end2)

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        if start >= end:
            return False

        # Check existing active appointments for the doctor
        for appt in self._appointments.values():
            if not appt.cancelled and appt.doctor == doctor:
                if self._overlaps(start, end, appt.start, appt.end):
                    return False

        # Check blocked slots from late cancellations
        for slot in self._blocked_slots:
            if slot.doctor == doctor:
                if self._overlaps(start, end, slot.start, slot.end):
                    return False

        return True

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        if start >= end:
            raise ValueError("Appointment start time must be before end time.")

        if start < now:
            raise ValueError("Cannot book an appointment that starts in the past.")

        # Check if the patient already has an upcoming appointment
        for appt in self._appointments.values():
            if not appt.cancelled and appt.patient == patient:
                # An appointment is upcoming if its end time (or start time) is in the future relative to `now`.
                # Typically, upcoming means it hasn't ended yet (or starts in the future).
                # Since start >= now is required for booking, checking appt.end > now covers any active/future ones.
                if appt.end > now:
                    raise ValueError(f"Patient '{patient}' already has an upcoming appointment.")

        # Check doctor availability
        if not self.is_free(doctor, start, end):
            raise ValueError(f"Doctor '{doctor}' is not available during the requested time slot.")

        appt_id = self._next_id
        self._next_id += 1
        self._appointments[appt_id] = Appointment(appt_id, patient, doctor, start, end)
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        """Cancel an appointment."""
        if appointment_id not in self._appointments:
            raise ValueError("Appointment does not exist.")

        appt = self._appointments[appointment_id]
        if appt.cancelled:
            raise ValueError("Appointment is already cancelled.")

        appt.cancelled = True

        # Cancelling less than 24 hours before start does not free the slot
        if appt.start - now < timedelta(hours=24):
            self._blocked_slots.append(BlockedSlot(appt.doctor, appt.start, appt.end))
